"use client"

import { zodResolver } from "@hookform/resolvers/zod"
import { Loader2 } from "lucide-react"
import * as z from "zod"

import * as React from "react"
import { useForm } from "react-hook-form"

import {
  AlertDialog,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog"
import { Button } from "@/components/ui/button"
import { Form } from "@/components/ui/form"

import { TsFormLayout } from "./ts-form-layout"
import { generateZodSchema } from "./ts-form-schema"
import { TsFormLayout as LayoutType, TsFieldDef, TsFormButton, TsFormConfirmation } from "./types"

export interface TsFormProps {
  layout: LayoutType
  fields: Record<string, TsFieldDef>
  values?: Record<string, unknown>
  buttons?: TsFormButton[]
  errors?: Record<string, string>
  onSubmit?: (data: Record<string, unknown>, action: string) => void
  readOnly?: boolean
  className?: string
}

export function TsForm({
  layout,
  fields,
  values,
  buttons = [],
  errors,
  onSubmit,
  className,
}: Omit<TsFormProps, "readOnly">) {
  // 1. Generate Schema based on fields
  const formSchema = React.useMemo(() => generateZodSchema(fields), [fields])
  type FormValues = z.infer<typeof formSchema>

  // 2. Initialize Form
  const form = useForm<FormValues>({
    resolver: zodResolver(formSchema),
    defaultValues: (values as FormValues) || {},
    mode: "onChange",
  })

  // Update form values when props change
  React.useEffect(() => {
    if (values) {
      form.reset(values as FormValues)
    }
  }, [values, form])

  // Handle external errors
  React.useEffect(() => {
    if (errors) {
      Object.entries(errors).forEach(([key, message]) => {
        form.setError(key as keyof FormValues, { type: "manual", message })
      })
    }
  }, [errors, form])

  const [submittingAction, setSubmittingAction] = React.useState<string | null>(null)

  // Confirmation State
  const [confirmation, setConfirmation] = React.useState<{
    isOpen: boolean
    config: TsFormConfirmation | null
    pendingAction: string | null
    pendingData: FormValues | null
  }>({ isOpen: false, config: null, pendingAction: null, pendingData: null })

  // 3. Handle Submit (called by form onSubmit)
  const onFormSubmit = React.useCallback(
    (data: FormValues) => {
      // This logic handles implicit submission via Enter key or direct button click

      if (submittingAction) {
        onSubmit?.(data as Record<string, unknown>, submittingAction)
        setSubmittingAction(null)
      } else {
        // Default submit (e.g. Enter key) - find primary submit button
        const submitBtn = buttons.find((b) => b.type === "submit") || buttons[0]
        if (submitBtn) {
          if (submitBtn.confirmation) {
            setConfirmation({
              isOpen: true,
              config: submitBtn.confirmation,
              pendingAction: submitBtn.action,
              pendingData: data,
            })
          } else {
            onSubmit?.(data as Record<string, unknown>, submitBtn.action)
          }
        }
      }
    },
    [submittingAction, onSubmit, buttons]
  )

  // Handle field-level keyboard actions (Enter/Escape)
  React.useEffect(() => {
    const handleKeyAction = (e: Event) => {
      const customEvent = e as CustomEvent<{ key: string; action: string; field: string }>
      const { key, action } = customEvent.detail

      if (key === "Enter") {
        if (action === "submit") {
          form.handleSubmit(onFormSubmit)()
        } else if (action === "focus:next") {
          // Find next focusable element in the form
          const formElement = (e.target as HTMLElement).closest("form")
          if (formElement) {
            const inputs = Array.from(
              formElement.querySelectorAll("input, textarea, select, button")
            ).filter((el) => {
              const htmlEl = el as
                | HTMLInputElement
                | HTMLTextAreaElement
                | HTMLSelectElement
                | HTMLButtonElement
              return !htmlEl.disabled && htmlEl.tabIndex !== -1 && htmlEl.offsetParent !== null
            })
            const currentIndex = inputs.indexOf(e.target as Element)
            if (currentIndex !== -1 && currentIndex < inputs.length - 1) {
              ;(inputs[currentIndex + 1] as HTMLElement).focus()
            }
          }
        }
      } else if (key === "Escape") {
        if (action === "clear") {
          // The clearing is already handled at the field level in ts-form-field.tsx
          // but we can add additional logic here if needed.
        } else if (action === "cancel") {
          // Logic for cancel if needed
        }
      }
    }

    window.addEventListener("form-key-action", handleKeyAction)
    return () => window.removeEventListener("form-key-action", handleKeyAction)
  }, [form, onFormSubmit])

  const handleButtonClick = (e: React.MouseEvent, btn: TsFormButton) => {
    if (btn.confirmation) {
      e.preventDefault()

      const proceedWithConfirmation = (data: FormValues) => {
        setConfirmation({
          isOpen: true,
          config: btn.confirmation!,
          pendingAction: btn.action,
          pendingData: data,
        })
      }

      if (!btn.type || btn.type === "submit") {
        // Trigger validation first
        form.handleSubmit(proceedWithConfirmation)(e)
      } else {
        // No validation for non-submit buttons
        proceedWithConfirmation(form.getValues() as FormValues)
      }
      return
    }

    // Normal flow
    if (!btn.type || btn.type === "submit") {
      setSubmittingAction(btn.action)
      // form onSubmit will be called
    } else {
      e.preventDefault()
      onSubmit?.(form.getValues() as Record<string, unknown>, btn.action)
    }
  }

  const handleConfirmationAction = (btnConfig: { action: string; confirm?: boolean }) => {
    if (btnConfig.confirm && confirmation.pendingAction && confirmation.pendingData) {
      onSubmit?.(confirmation.pendingData as Record<string, unknown>, confirmation.pendingAction)
    }
    setConfirmation((prev) => ({ ...prev, isOpen: false }))
  }

  const renderButtons = (btns: (TsFormButton | TsFormConfirmation["buttons"][0])[]) => {
    return btns.map((btn, idx) => {
      // Map variants
      type ButtonVariant = "default" | "destructive" | "outline" | "secondary" | "ghost" | "link"
      let variant: ButtonVariant = "default"
      let customClass = ""

      if (btn.variant === "primary") {
        customClass = "bg-blue-600 text-white hover:bg-blue-700 border-none"
      } else if (btn.variant === "success") {
        customClass = "bg-green-600 text-white hover:bg-green-700 border-none"
      } else if (btn.variant === "warning") {
        customClass = "bg-amber-500 text-white hover:bg-amber-600 border-none"
      } else if (btn.variant === "danger" || btn.variant === "destructive") {
        variant = "destructive"
      } else if (
        btn.variant === "default" ||
        btn.variant === "outline" ||
        btn.variant === "secondary" ||
        btn.variant === "ghost" ||
        btn.variant === "link"
      ) {
        variant = btn.variant
      }

      // Check if it's a confirmation button
      const isConfirmBtn = "confirm" in btn

      return (
        <Button
          key={idx}
          type={!isConfirmBtn ? (btn as TsFormButton).type || "submit" : "button"}
          variant={variant}
          className={customClass}
          onClick={(e) => {
            if (isConfirmBtn) {
              handleConfirmationAction(btn as TsFormConfirmation["buttons"][0])
            } else {
              handleButtonClick(e, btn as TsFormButton)
            }
          }}
          disabled={
            !isConfirmBtn &&
            form.formState.isSubmitting &&
            submittingAction === (btn as TsFormButton).action
          }
        >
          {!isConfirmBtn &&
            form.formState.isSubmitting &&
            submittingAction === (btn as TsFormButton).action && (
              <Loader2 className="mr-2 h-4 w-4 animate-spin" />
            )}
          {btn.label}
        </Button>
      )
    })
  }

  return (
    <>
      <Form {...form}>
        <form onSubmit={form.handleSubmit(onFormSubmit)} className={className}>
          <TsFormLayout layout={layout} fields={fields} />

          {/* Buttons Bar */}
          {buttons.length > 0 && (
            <div className="flex items-center justify-between gap-2 mt-6 pt-4 border-t w-full">
              <div className="flex flex-1 flex-row items-center justify-start gap-2">
                {renderButtons(buttons.filter((b) => b.position === "left"))}
              </div>
              <div className="flex flex-1 flex-row items-center justify-center gap-2">
                {renderButtons(buttons.filter((b) => b.position === "center"))}
              </div>
              <div className="flex flex-1 flex-row items-center justify-end gap-2">
                {renderButtons(buttons.filter((b) => !b.position || b.position === "right"))}
              </div>
            </div>
          )}
        </form>
      </Form>

      {/* Confirmation Dialog */}
      {confirmation.config && (
        <AlertDialog
          open={confirmation.isOpen}
          onOpenChange={(open: boolean) => setConfirmation((prev) => ({ ...prev, isOpen: open }))}
        >
          <AlertDialogContent className="max-w-2xl">
            <AlertDialogHeader>
              <AlertDialogTitle>{confirmation.config.title}</AlertDialogTitle>
              <AlertDialogDescription>{confirmation.config.text}</AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter className="flex items-center justify-between gap-2 w-full sm:justify-between flex-row">
              <div className="flex items-center gap-2">
                {renderButtons(confirmation.config.buttons.filter((b) => b.position === "left"))}
              </div>
              <div className="flex items-center gap-2">
                {renderButtons(confirmation.config.buttons.filter((b) => b.position === "center"))}
              </div>
              <div className="flex items-center gap-2 sm:space-x-0 sm:justify-end">
                {renderButtons(
                  confirmation.config.buttons.filter((b) => !b.position || b.position === "right")
                )}
              </div>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
      )}
    </>
  )
}

"use client"

import { format, isValid as isValidDate, parse } from "date-fns"
import {
  AlertTriangle,
  CalendarIcon,
  Check,
  CheckCircle2,
  ChevronsUpDown,
  CloudUpload,
  Copy,
  Download,
  FileText as FileTextIcon,
  Info,
  X as XIcon,
} from "lucide-react"
import remarkGfm from "remark-gfm"

import * as React from "react"
import { ControllerRenderProps, FieldValues, useFormContext } from "react-hook-form"
import Markdown from "react-markdown"

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Calendar } from "@/components/ui/calendar"
import { Checkbox } from "@/components/ui/checkbox"
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command"
import {
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form"
import { Input } from "@/components/ui/input"
import { Popover, PopoverAnchor, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Slider } from "@/components/ui/slider"
import { Switch } from "@/components/ui/switch"
import { Textarea } from "@/components/ui/textarea"

import { cn } from "@/lib/utils"

import { TsTable } from "@/components/ts-web-ui/ts-table"
import {
  TsButtonGroupField,
  TsComboboxField,
  TsDateField,
  TsDateTimeField,
  TsFieldDef,
  TsFieldOptions,
  TsFileField,
  TsMultiselectField,
  TsNumberField,
  TsRelationshipField,
  TsSliderField,
} from "./types"

interface TsFormFieldProps {
  name: string
  fieldDef: TsFieldDef
}

export function TsFormField({ name, fieldDef }: TsFormFieldProps) {
  const form = useFormContext()
  const hasError = !!fieldDef.error

  return (
    <FormField
      control={form.control}
      name={name}
      render={({ field }) => (
        <FormItem
          className={cn(fieldDef.hidden && "hidden", hasError && "[&_label]:text-destructive")}
        >
          {/* Label is rendered unless it's a checkbox/switch/infobox/button/separator/empty/markdown */}
          {fieldDef.type !== "checkbox" &&
            fieldDef.type !== "switch" &&
            fieldDef.type !== "infobox" &&
            fieldDef.type !== "button" &&
            fieldDef.type !== "separator" &&
            fieldDef.type !== "empty" &&
            fieldDef.type !== "markdown" && (
              <FormLabel className={cn(hasError && "text-destructive")}>
                {fieldDef.required ? `${fieldDef.label} *` : fieldDef.label}
              </FormLabel>
            )}

          <FormControl>{renderWidget(field, fieldDef, name, hasError)}</FormControl>

          {/* Error message has priority over hint */}
          {hasError ? (
            <p className="text-sm text-destructive leading-none">{fieldDef.error}</p>
          ) : (
            fieldDef.hint && (
              <FormDescription className="leading-none">{fieldDef.hint}</FormDescription>
            )
          )}
          <FormMessage />
        </FormItem>
      )}
    />
  )
}

function renderWidget(
  field: ControllerRenderProps<FieldValues, string>,
  def: TsFieldDef,
  name: string,
  hasError: boolean = false
) {
  const handleKeyDown = (e: React.KeyboardEvent) => {
    // Extract actions reliably from any field type
    const enterAction = (def as unknown as Record<string, unknown>).enterAction as string | undefined
    const escapeAction = (def as unknown as Record<string, unknown>).escapeAction as string | undefined

    if (e.key === "Enter") {
      if (enterAction) {
        e.preventDefault()
        e.stopPropagation()
        const event = new CustomEvent("form-key-action", {
          detail: { key: "Enter", action: enterAction, field: name },
          bubbles: true,
        })
        ;(e.currentTarget as HTMLElement).dispatchEvent(event)
      }
    } else if (e.key === "Escape") {
      e.preventDefault()
      e.stopPropagation()
      if (!escapeAction || escapeAction === "clear") {
        field.onChange("")
      }

      if (escapeAction) {
        const event = new CustomEvent("form-key-action", {
          detail: { key: "Escape", action: escapeAction, field: name },
          bubbles: true,
        })
        ;(e.currentTarget as HTMLElement).dispatchEvent(event)
      }
    }
  }

  // Shared classes for error state and readonly styling
  const errorClass = hasError ? "border-destructive focus-visible:ring-destructive" : ""
  const readonlyClass = def.readonly ? "focus-visible:ring-0 focus-visible:border-input" : ""
  // For button/interactive widgets: block pointer events instead of disabling (to preserve normal look)
  const readonlyPointerClass = def.readonly ? "pointer-events-none" : ""

  switch (def.type) {
    case "text":
    case "password":
      return (
        <Input
          type={def.type}
          placeholder={def.placeholder}
          {...field}
          value={(field.value as string) ?? ""}
          onKeyDown={handleKeyDown}
          disabled={def.disabled}
          readOnly={def.readonly}
          tabIndex={def.readonly ? -1 : undefined}
          onFocus={(e) => {
            if (def.readonly) {
              e.currentTarget.blur()
              return
            }
            if (def.selectAllOnFocus) {
              const el = e.currentTarget
              setTimeout(() => el.select(), 0)
            }
          }}
          onClick={(e) => {
            if (def.selectAllOnFocus) e.currentTarget.select()
          }}
          className={cn(errorClass, readonlyClass)}
        />
      )

    case "number":
      return <NumberWidget field={field} def={def} hasError={hasError} name={name} />

    case "textarea":
      return (
        <Textarea
          placeholder={def.placeholder}
          {...field}
          value={(field.value as string) ?? ""}
          rows={def.rows || 3}
          onKeyDown={handleKeyDown}
          disabled={def.disabled}
          readOnly={def.readonly}
          tabIndex={def.readonly ? -1 : undefined}
          onFocus={(e) => {
            if (def.readonly) {
              e.currentTarget.blur()
              return
            }
            if (def.selectAllOnFocus) {
              const el = e.currentTarget
              setTimeout(() => el.select(), 0)
            }
          }}
          onClick={(e) => {
            if (def.selectAllOnFocus) e.currentTarget.select()
          }}
          className={cn("field-sizing-fixed", errorClass, readonlyClass)}
          style={def.rows ? { height: `${def.rows * 1.5 + 1}rem` } : undefined}
        />
      )

    case "checkbox":
      return (
        <div className={cn("flex items-center space-x-2", readonlyPointerClass)}>
          <Checkbox
            checked={!!field.value}
            onCheckedChange={field.onChange}
            disabled={def.disabled}
            className={cn(hasError && "border-destructive data-[state=checked]:bg-destructive")}
          />
          <FormLabel className={cn("font-normal cursor-pointer", hasError && "text-destructive")}>
            {def.required ? `${def.label} *` : def.label}
          </FormLabel>
        </div>
      )

    case "switch":
      return (
        <div className={cn("flex items-center space-x-2", readonlyPointerClass)}>
          <Switch
            checked={!!field.value}
            onCheckedChange={field.onChange}
            disabled={def.disabled}
            className={cn(
              hasError &&
                "data-[state=checked]:bg-destructive data-[state=unchecked]:bg-destructive/30"
            )}
          />
          <FormLabel className={cn("font-normal cursor-pointer", hasError && "text-destructive")}>
            {def.required ? `${def.label} *` : def.label}
          </FormLabel>
        </div>
      )

    case "radio":
      return (
        <RadioGroup
          onValueChange={field.onChange}
          defaultValue={field.value}
          disabled={def.disabled}
          className={cn(
            "flex flex-col gap-2",
            hasError && "[&_button]:border-destructive",
            readonlyPointerClass
          )}
        >
          {(def.options || []).map((opt: TsFieldOptions | string) => {
            const value = typeof opt === "string" ? opt : String(opt.value)
            const label = typeof opt === "string" ? opt : opt.label
            return (
              <div key={value} className="flex items-center space-x-2">
                <RadioGroupItem value={value} id={`${field.name}-${value}`} />
                <FormLabel
                  htmlFor={`${field.name}-${value}`}
                  className={cn("font-normal cursor-pointer", hasError && "text-destructive")}
                >
                  {label}
                </FormLabel>
              </div>
            )
          })}
        </RadioGroup>
      )

    case "button-group":
      if (def.variant === "process") {
        return <ProcessButtonGroup field={field} def={def} hasError={hasError} />
      }
      return (
        <div
          className={cn(
            "flex",
            def.disabled && "opacity-50 pointer-events-none",
            readonlyPointerClass
          )}
        >
          {(def.options || []).map((opt: TsFieldOptions | string, index, arr) => {
            let value: string
            let label: string
            let optVariant: string | undefined
            let isDisabled = false

            if (typeof opt === "string") {
              const parts = opt.split("/")
              // Format: value/enabled/variant/label
              value = parts[0]
              isDisabled = parts[1] === "false"
              optVariant = parts[2] || undefined
              label = parts[3] || parts[0]
            } else {
              value = String(opt.value)
              label = opt.label
              optVariant = opt.variant
              isDisabled = !!opt.disabled
            }

            const isActive = field.value === value
            const isFirst = index === 0
            const isLast = index === arr.length - 1
            // Mapping to Shadcn/UI variants:
            const rawVariant = isActive
              ? optVariant || "default"
              : optVariant
                ? optVariant
                : "outline"

            let variant: "default" | "destructive" | "outline" | "secondary" | "ghost" | "link" =
              "outline"
            if (rawVariant === "destructive" || rawVariant === "danger") variant = "destructive"
            else if (rawVariant === "secondary") variant = "secondary"
            else if (rawVariant === "ghost") variant = "ghost"
            else if (rawVariant === "link") variant = "link"
            else if (rawVariant === "outline") variant = "outline"
            else variant = "default" // default, primary, success, warning map to default

            return (
              <Button
                key={value}
                type="button"
                variant={variant}
                disabled={def.disabled || isDisabled}
                className={cn(
                  !isFirst && "-ml-px",
                  isFirst && !isLast && "rounded-r-none",
                  isLast && !isFirst && "rounded-l-none",
                  !isFirst && !isLast && "rounded-none",
                  isActive && "relative z-10",
                  hasError && "border-destructive text-destructive"
                )}
                onClick={() => {
                  if (!def.disabled && !def.readonly && !isDisabled) field.onChange(value)
                }}
              >
                {label}
              </Button>
            )
          })}
        </div>
      )

    case "slider":
      return <SliderWithTooltip field={field} def={def} hasError={hasError} />

    case "select":
      return (
        <Select onValueChange={field.onChange} value={field.value} disabled={def.disabled}>
          <SelectTrigger className={cn(errorClass, def.readonly ? "pointer-events-none" : "")}>
            <SelectValue placeholder={def.placeholder || "Select..."} />
          </SelectTrigger>
          <SelectContent>
            {(def.options || []).map((opt: TsFieldOptions | string) => {
              const value = typeof opt === "string" ? opt : String(opt.value)
              const label = typeof opt === "string" ? opt : opt.label
              return (
                <SelectItem key={value} value={value}>
                  {label}
                </SelectItem>
              )
            })}
          </SelectContent>
        </Select>
      )

    case "combobox":
      return <ComboboxWidget field={field} def={def} hasError={hasError} />

    case "multiselect":
      return <MultiSelectWidget field={field} def={def} hasError={hasError} />

    case "date":
      return <DatePickerWidget field={field} def={def} hasError={hasError} />

    case "datetime":
      return <DateTimeWidget field={field} def={def} hasError={hasError} />

    case "file":
    case "image":
      return <FileUploadWidget field={field} def={def} hasError={hasError} />

    case "infobox": {
      const v = def.variant || "default"
      const variantClasses: Record<string, string> = {
        destructive:
          "border-destructive/50 bg-destructive/10 text-destructive dark:text-red-400 [&>svg]:text-destructive",
        information:
          "border-blue-500/50 bg-blue-500/10 text-blue-700 dark:text-blue-400 [&>svg]:text-blue-500",
        warning:
          "border-amber-500/50 bg-amber-500/10 text-amber-700 dark:text-amber-400 [&>svg]:text-amber-500",
        success:
          "border-green-500/50 bg-green-500/10 text-green-700 dark:text-green-400 [&>svg]:text-green-500",
      }
      const iconMap: Record<string, React.ReactNode> = {
        default: <Info className="h-4 w-4" />,
        destructive: <Info className="h-4 w-4" />,
        information: <Info className="h-4 w-4" />,
        warning: <AlertTriangle className="h-4 w-4" />,
        success: <CheckCircle2 className="h-4 w-4" />,
      }
      return (
        <Alert variant="default" className={variantClasses[v] || ""}>
          {iconMap[v] || <Info className="h-4 w-4" />}
          {def.label && <AlertTitle>{def.label}</AlertTitle>}
          <AlertDescription>{(def.value as React.ReactNode) || def.content || ""}</AlertDescription>
        </Alert>
      )
    }

    case "markdown":
      return (
        <div className="prose prose-sm dark:prose-invert max-w-none [&_table]:w-full [&_table]:border-collapse [&_th]:border [&_th]:border-border [&_th]:p-2 [&_td]:border [&_td]:border-border [&_td]:p-2">
          <Markdown
            remarkPlugins={[remarkGfm]}
            components={{
              /* eslint-disable-next-line @typescript-eslint/no-unused-vars, @typescript-eslint/no-explicit-any */
              a: ({ node, ...props }: any) => (
                <a {...props} target="_blank" rel="noopener noreferrer" />
              ),
              /* eslint-disable-next-line @typescript-eslint/no-unused-vars, @typescript-eslint/no-explicit-any */
              code: ({ node, inline, className, children, ...props }: any) => {
                if (inline) {
                  return (
                    <code className={className} {...props}>
                      {children}
                    </code>
                  )
                }
                return (
                  <div className="relative group">
                    <MarkdownCopyButton text={String(children)} />
                    <code className={className} {...props}>
                      {children}
                    </code>
                  </div>
                )
              },
            }}
          >
            {(def.value as string) || def.content || ""}
          </Markdown>
        </div>
      )

    case "table":
      return (
        <div className="border rounded-md p-2">
          <TsTable
            data={(field.value as Record<string, unknown>[]) || []}
            columnDefinitions={def.columns || []}
            showCreateButton={def.showCreateButton}
          />
        </div>
      )

    case "button":
      return (
        <Button
          variant={(def.variant as "default") || "default"}
          className="w-full"
          onClick={(e) => {
            e.preventDefault()
            // Dispatch custom event for bubbling
            const event = new CustomEvent("form-field-action", {
              detail: { field: name, action: def.action },
              bubbles: true,
            })
            e.currentTarget.dispatchEvent(event)
          }}
        >
          {def.label}
        </Button>
      )

    case "separator":
      // Separator - consistent height with or without label
      return (
        <div className="py-2">
          <div className="relative h-5 flex items-center">
            <div className="absolute inset-0 flex items-center">
              <span className="w-full border-t" />
            </div>
            {def.label && (
              <div className="relative flex justify-center w-full text-xs uppercase">
                <span className="bg-background px-2 text-muted-foreground font-medium">
                  {def.label}
                </span>
              </div>
            )}
          </div>
        </div>
      )

    case "empty":
      // Empty placeholder for layout purposes
      return <div className="min-h-10" />

    case "relationship":
      // Relationship picker for entity selection
      return <RelationshipWidget field={field} def={def} hasError={hasError} />

    // This default case should never be reached if all TsFieldDef union members are handled above.
    // The compile-time exhaustiveness check below will error if a new type is added to TsFieldDef
    // without a corresponding case in this switch.
    default: {
      const _exhaustive: never = def
      const unknown = _exhaustive as { type: string }
      return (
        <div className="p-2 border border-destructive/50 text-destructive text-sm rounded bg-destructive/10">
          Unsupported widget: {unknown.type}
        </div>
      )
    }
  }
}

function ComboboxWidget({
  field,
  def,
  hasError = false,
}: {
  field: ControllerRenderProps<FieldValues, string>
  def: TsComboboxField
  hasError?: boolean
}) {
  const [open, setOpen] = React.useState(false)
  const [searchValue, setSearchValue] = React.useState("")
  const options = (def.options || []).map((opt: TsFieldOptions | string) => {
    const value = typeof opt === "string" ? opt : String(opt.value)
    const label = typeof opt === "string" ? opt : opt.label
    return { value, label }
  })

  // Allow custom value if not found (exact match)
  const showCustom =
    def.allowCustom &&
    searchValue &&
    !options.find((o) => o.label.toLowerCase() === searchValue.toLowerCase())

  const errorClass = hasError ? "border-destructive focus-visible:ring-destructive" : ""
  const readonlyClass = def.readonly ? "pointer-events-none" : ""

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          variant="outline"
          role="combobox"
          aria-expanded={open}
          aria-controls={`popover-content-${name}`}
          className={cn(
            "w-full justify-between hover:bg-background dark:hover:bg-input/30",
            errorClass,
            readonlyClass
          )}
          disabled={def.disabled}
        >
          {field.value
            ? (options.find((framework) => framework.value === field.value)?.label ??
              (field.value as string))
            : def.placeholder || "Select..."}
          <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
        </Button>
      </PopoverTrigger>
      <PopoverContent
        id={`popover-content-${name}`}
        className="w-full p-0"
        onOpenAutoFocus={(e) => {
          e.preventDefault()
          ;(e.currentTarget as HTMLElement).querySelector("input")?.focus()
        }}
        onEscapeKeyDown={(e) => {
          if (searchValue) {
            e.preventDefault()
            setSearchValue("")
          }
        }}
      >
        <Command
          filter={(value, search) => (value.toLowerCase().includes(search.toLowerCase()) ? 1 : 0)}
        >
          <CommandInput
            placeholder={def.placeholder || "Search..."}
            value={searchValue}
            onValueChange={setSearchValue}
          />
          <CommandList>
            <CommandEmpty className="py-1.5 px-2 text-left">
              <span className="italic text-muted-foreground text-sm">
                {def.notFoundMessage || "Not found."}
              </span>
            </CommandEmpty>
            <CommandGroup>
              {options.map((framework) => (
                <CommandItem
                  key={framework.value}
                  value={framework.label}
                  onSelect={(currentValue: string) => {
                    const original = options.find(
                      (o) => o.label.toLowerCase() === currentValue.toLowerCase()
                    )
                    field.onChange(original ? original.value : currentValue)
                    setSearchValue("")
                    setOpen(false)
                  }}
                >
                  <Check
                    className={cn(
                      "mr-2 h-4 w-4",
                      field.value === framework.value ? "opacity-100" : "opacity-0"
                    )}
                  />
                  {framework.label}
                </CommandItem>
              ))}
              {showCustom && (
                <CommandItem
                  value={`\x00custom:${searchValue}`}
                  onSelect={() => {
                    field.onChange(searchValue)
                    setSearchValue("")
                    setOpen(false)
                  }}
                >
                  <Check className="mr-2 h-4 w-4 opacity-0" />
                  Use: &quot;{searchValue}&quot;
                </CommandItem>
              )}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  )
}

function MultiSelectWidget({
  field,
  def,
  hasError = false,
}: {
  field: ControllerRenderProps<FieldValues, string>
  def: TsMultiselectField
  hasError?: boolean
}) {
  const [open, setOpen] = React.useState(false)
  const [searchValue, setSearchValue] = React.useState("")
  const selectedValues: string[] = Array.isArray(field.value) ? (field.value as string[]) : []
  const options = (def.options || []).map((opt: TsFieldOptions | string) => {
    const value = typeof opt === "string" ? opt : String(opt.value)
    const label = typeof opt === "string" ? opt : opt.label
    return { value, label }
  })

  const toggleValue = (val: string) => {
    const newValues = selectedValues.includes(val)
      ? selectedValues.filter((v) => v !== val)
      : [...selectedValues, val]
    field.onChange(newValues)
  }

  const errorClass = hasError ? "border-destructive focus-visible:ring-destructive" : ""

  return (
    <Popover open={open} onOpenChange={setOpen} modal>
      {/* Use PopoverAnchor so the container div has no Radix click listener —
          X badge clicks can stopPropagation in React without being overridden */}
      <PopoverAnchor asChild>
        <div
          role="combobox"
          aria-expanded={open}
          aria-controls={`popover-content-${name}`}
          tabIndex={def.disabled || def.readonly ? -1 : 0}
          onClick={() => {
            if (!def.disabled && !def.readonly) setOpen((v) => !v)
          }}
          onKeyDown={(e) => {
            if ((e.key === "Enter" || e.key === " ") && !def.disabled && !def.readonly) {
              e.preventDefault()
              setOpen((v) => !v)
            }
          }}
          className={cn(
            "flex min-h-10 w-full cursor-pointer items-center justify-between rounded-md border bg-background px-3 py-2 text-sm shadow-xs",
            "hover:bg-accent dark:hover:bg-input/30",
            "focus-visible:outline-none focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px]",
            errorClass,
            def.disabled && "opacity-50 pointer-events-none",
            def.readonly && "pointer-events-none"
          )}
        >
          <div className="flex flex-wrap gap-1">
            {selectedValues.length > 0 ? (
              selectedValues.map((val) => (
                <Badge key={val} variant="secondary" className="mr-1">
                  {options.find((o) => o.value === val)?.label || val}
                  {/* Badge applies [&>svg]:pointer-events-none to direct SVG children,
                      so wrap XIcon in a span to keep onClick functional */}
                  <span
                    role="button"
                    tabIndex={0}
                    className="ml-1 inline-flex cursor-pointer items-center hover:text-destructive"
                    onClick={(e) => {
                      e.stopPropagation()
                      toggleValue(val)
                    }}
                    onKeyDown={(e) => {
                      if (e.key === "Enter" || e.key === " ") {
                        e.preventDefault()
                        e.stopPropagation()
                        toggleValue(val)
                      }
                    }}
                  >
                    <XIcon className="h-3 w-3" />
                  </span>
                </Badge>
              ))
            ) : (
              <span className="text-muted-foreground">{def.placeholder || "Select..."}</span>
            )}
          </div>
          <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
        </div>
      </PopoverAnchor>
      <PopoverContent
        id={`popover-content-${name}`}
        className="w-full p-0"
        onOpenAutoFocus={(e) => {
          e.preventDefault()
          ;(e.currentTarget as HTMLElement).querySelector("input")?.focus()
        }}
        onEscapeKeyDown={(e) => {
          if (searchValue) {
            e.preventDefault()
            setSearchValue("")
          }
        }}
      >
        <Command
          filter={(value, search) => (value.toLowerCase().includes(search.toLowerCase()) ? 1 : 0)}
        >
          <CommandInput
            placeholder={def.placeholder || "Search..."}
            value={searchValue}
            onValueChange={setSearchValue}
          />
          <CommandList>
            <CommandEmpty className="py-1.5 px-2 text-left">
              <span className="italic text-muted-foreground text-sm">
                {def.notFoundMessage || "Not found."}
              </span>
            </CommandEmpty>
            <CommandGroup>
              {options.map((opt) => (
                <CommandItem
                  key={opt.value}
                  value={opt.label}
                  onSelect={() => toggleValue(opt.value)}
                >
                  <Check
                    className={cn(
                      "mr-2 h-4 w-4",
                      selectedValues.includes(opt.value) ? "opacity-100" : "opacity-0"
                    )}
                  />
                  {opt.label}
                </CommandItem>
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  )
}

/**
 * Relationship Widget - allows selecting entities from a relational table
 * Supports single or multiple selection modes
 */
function RelationshipWidget({
  field,
  def,
  hasError = false,
}: {
  field: ControllerRenderProps<FieldValues, string>
  def: TsRelationshipField
  hasError?: boolean
}) {
  const [open, setOpen] = React.useState(false)
  const [searchValue, setSearchValue] = React.useState("")

  // Configuration from field definition
  const mode = def.mode || "single"
  const targetEntity = def.targetEntity || ""

  const displayFields = React.useMemo(() => def.displayFields || ["name"], [def.displayFields])
  const chipDisplayFields = React.useMemo(
    () => def.chipDisplayFields || displayFields,
    [def.chipDisplayFields, displayFields]
  )

  const valueField = def.valueField || "id"
  const availableItems = React.useMemo(
    () => (def.options as unknown as Record<string, unknown>[]) || [],
    [def.options]
  )

  const errorClass = hasError ? "border-destructive focus-visible:ring-destructive" : ""
  const readonlyClass = def.readonly ? "pointer-events-none" : ""

  // Value parsing - can be single ID, array ID or object/objects
  const selectedValues = React.useMemo(() => {
    if (!field.value) return []
    return Array.isArray(field.value) ? (field.value as unknown[]) : [field.value]
  }, [field.value])

  /**
   * Gets display text for an item
   */
  const getDisplayText = (item: unknown, fields: string[]) => {
    if (!item) return ""
    if (typeof item !== "object") {
      // Find item by ID
      const found = availableItems.find((i) => i[valueField] === item)
      if (found) {
        return fields
          .map((f) => String(found[f]))
          .filter(Boolean)
          .join(" ")
      }
      return String(item)
    }
    const obj = item as Record<string, unknown>
    return fields
      .map((f) => String(obj[f]))
      .filter(Boolean)
      .join(" ")
  }

  /**
   * Filters items based on search text
   */
  const filteredItems = React.useMemo(() => {
    if (!searchValue) return availableItems
    const lower = searchValue.toLowerCase()
    return availableItems.filter((item) => {
      const text = displayFields
        .map((f: string) => String(item[f]))
        .filter(Boolean)
        .join(" ")
        .toLowerCase()
      return text.includes(lower)
    })
  }, [availableItems, searchValue, displayFields])

  /**
   * Selects/removes an item
   */
  const toggleItem = (item: Record<string, unknown>) => {
    const itemValue = item[valueField]

    if (mode === "single") {
      field.onChange(itemValue)
      setOpen(false)
    } else {
      const isSelected = selectedValues.includes(itemValue)
      if (isSelected) {
        field.onChange(selectedValues.filter((v) => v !== itemValue))
      } else {
        field.onChange([...selectedValues, itemValue])
      }
    }
  }

  /**
   * Removes item from selection (for chip)
   */
  const removeItem = (itemValue: unknown) => {
    if (mode === "single") {
      field.onChange(null)
    } else {
      field.onChange(selectedValues.filter((v) => v !== itemValue))
    }
  }

  /**
   * Checks if item is selected
   */
  const isSelected = (item: Record<string, unknown>) => selectedValues.includes(item[valueField])

  return (
    <Popover open={open} onOpenChange={setOpen} modal>
      {/* Use PopoverAnchor so the container div has no Radix click listener —
          X badge clicks can stopPropagation in React without being overridden */}
      <PopoverAnchor asChild>
        {/* Input-like container with chips inside */}
        <div
          role="combobox"
          aria-expanded={open}
          aria-controls={`popover-content-${name}`}
          tabIndex={def.disabled || def.readonly ? -1 : 0}
          onClick={() => {
            if (!def.disabled && !def.readonly) setOpen((v) => !v)
          }}
          onKeyDown={(e) => {
            if ((e.key === "Enter" || e.key === " ") && !def.disabled && !def.readonly) {
              e.preventDefault()
              setOpen((v) => !v)
            }
          }}
          className={cn(
            "flex h-9 w-full items-center justify-between gap-2 rounded-md border bg-background px-3 py-1 text-sm shadow-xs cursor-pointer",
            "dark:bg-input/30 transition-[color,box-shadow]",
            !readonlyClass &&
              "focus-visible:outline-none focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px]",
            def.disabled && "opacity-50 pointer-events-none",
            readonlyClass && "pointer-events-none",
            errorClass
          )}
        >
          {/* Chips + placeholder area */}
          <div className="flex flex-1 items-center gap-1 overflow-hidden min-w-0 flex-nowrap">
            {selectedValues.length === 0 ? (
              <span className="text-muted-foreground truncate">
                {def.placeholder || `Select ${targetEntity}...`}
              </span>
            ) : (
              <>
                {selectedValues.slice(0, 3).map((val) => (
                  <Badge
                    key={String(val)}
                    variant="secondary"
                    className="shrink-0 gap-1 text-xs h-6 max-w-30"
                  >
                    <span className="truncate">{getDisplayText(val, chipDisplayFields)}</span>
                    {!def.readonly && !def.disabled && (
                      /* Badge applies [&>svg]:pointer-events-none to direct SVG children;
                         wrap in span so onClick fires */
                      <span
                        role="button"
                        tabIndex={0}
                        className="inline-flex cursor-pointer shrink-0 items-center hover:text-destructive"
                        onClick={(e) => {
                          e.stopPropagation()
                          removeItem(val)
                        }}
                        onKeyDown={(e) => {
                          if (e.key === "Enter" || e.key === " ") {
                            e.preventDefault()
                            e.stopPropagation()
                            removeItem(val)
                          }
                        }}
                      >
                        <XIcon className="h-2.5 w-2.5" />
                      </span>
                    )}
                  </Badge>
                ))}
                {selectedValues.length > 3 && (
                  <Badge variant="outline" className="shrink-0 text-xs h-6 whitespace-nowrap">
                    +{selectedValues.length - 3}
                  </Badge>
                )}
              </>
            )}
          </div>

          {/* Right controls */}
          <div className="flex items-center gap-1 shrink-0 ml-1">
            {selectedValues.length > 0 && !def.readonly && !def.disabled && (
              <XIcon
                className="h-3.5 w-3.5 text-muted-foreground hover:text-foreground cursor-pointer"
                onClick={(e) => {
                  e.stopPropagation()
                  field.onChange(mode === "single" ? null : [])
                  setOpen(false)
                }}
              />
            )}
            <ChevronsUpDown className="h-4 w-4 text-muted-foreground opacity-50" />
          </div>
        </div>
      </PopoverAnchor>
      <PopoverContent
        className="w-auto min-w-75 p-0"
        align="start"
        onOpenAutoFocus={(e) => {
          e.preventDefault()
          ;(e.currentTarget as HTMLElement).querySelector("input")?.focus()
        }}
        onEscapeKeyDown={(e) => {
          if (searchValue) {
            e.preventDefault()
            setSearchValue("")
          }
        }}
      >
        <Command shouldFilter={false}>
          <CommandInput
            placeholder={`Search ${targetEntity}...`}
            value={searchValue}
            onValueChange={setSearchValue}
          />
          <CommandList className="max-h-60">
            <CommandEmpty className="py-1.5 px-2 text-left">
              <span className="italic text-muted-foreground text-sm">
                {availableItems.length === 0 ? `No items in ${targetEntity}` : "Not found."}
              </span>
            </CommandEmpty>
            <CommandGroup>
              {filteredItems.map((item) => (
                <CommandItem
                  key={String(item[valueField])}
                  value={String(item[valueField])}
                  onSelect={() => toggleItem(item)}
                >
                  <Check
                    className={cn("mr-2 h-4 w-4", isSelected(item) ? "opacity-100" : "opacity-0")}
                  />
                  {getDisplayText(item, displayFields)}
                </CommandItem>
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  )
}

// ─── Helper functions for number formatting ──────────────────────────────────

function evaluateMathExpression(expression: string): number | undefined {
  try {
    // Replace comma with dot
    let expr = expression.replace(/,/g, ".")
    // Replace ^ with **
    expr = expr.replace(/\\^/g, "**")
    // Validate characters: only numbers, operators, brackets and spaces
    if (/[^0-9.+*/^() -]/.test(expr)) return undefined

    // Use Function constructor for evaluation
    const result = new Function(`return ${expr}`)()
    if (!isFinite(result) || isNaN(result)) return undefined
    return result
  } catch {
    return undefined
  }
}

function formatNumericValue(val: number | null | undefined, roundTo?: number): string {
  if (val === null || val === undefined || isNaN(val)) return ""
  let num = val
  if (roundTo !== undefined) {
    num = Math.round(num * Math.pow(10, roundTo)) / Math.pow(10, roundTo)
  }
  return new Intl.NumberFormat(undefined, {
    useGrouping: true,
    minimumFractionDigits: 0,
    maximumFractionDigits: roundTo !== undefined ? roundTo : 10,
  }).format(num)
}

function parseNumericValue(text: string): number | undefined {
  if (!text.trim()) return undefined

  // If it contains math operators, try to evaluate it
  if (/[+*/^() -]/.test(text)) {
    return evaluateMathExpression(text)
  }

  const clean = text.replace(/\\s/g, "").replace(",", ".")
  const num = parseFloat(clean)
  return isNaN(num) ? undefined : num
}

// ─── NumberWidget ─────────────────────────────────────────────────────────────

function NumberWidget({
  field,
  def,
  hasError = false,
  name,
}: {
  field: ControllerRenderProps<FieldValues, string>
  def: TsNumberField
  hasError?: boolean
  name: string
}) {
  const [displayValue, setDisplayValue] = React.useState<string>(() =>
    formatNumericValue(field.value as number | undefined, def.roundTo)
  )
  const [isFocused, setIsFocused] = React.useState(false)
  const isClearingRef = React.useRef(false)

  const errorClass = hasError ? "border-destructive focus-visible:ring-destructive" : ""
  const readonlyClass = def.readonly ? "focus-visible:ring-0 focus-visible:border-input" : ""

  React.useEffect(() => {
    if (!isFocused) {
      setDisplayValue(formatNumericValue(field.value as number | undefined, def.roundTo))
    }
  }, [field.value, isFocused, def.roundTo])

  const handleFocus = (e: React.FocusEvent<HTMLInputElement>) => {
    if (def.readonly) {
      e.currentTarget.blur()
      return
    }
    setIsFocused(true)
    isClearingRef.current = false
    // Remove thousands separators for editing
    const clean = displayValue.replace(/\s/g, "")
    setDisplayValue(clean)
    const el = e.currentTarget
    setTimeout(() => el.select(), 0)
  }

  const handleBlur = () => {
    setIsFocused(false)
    if (isClearingRef.current) {
      isClearingRef.current = false
      return
    }
    const num = parseNumericValue(displayValue)
    field.onChange(num)
    field.onBlur()
    setDisplayValue(formatNumericValue(num, def.roundTo))
  }

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value
    // Allow: digits, spaces, minus, comma, dot, and math operators
    const clean = val.replace(/[^0-9 .,+*/^()-]/g, "")
    setDisplayValue(clean !== val ? clean : val)
  }

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    const enterAction = def.enterAction
    const escapeAction = def.escapeAction || "clear"

    if (e.key === "Enter") {
      e.preventDefault()
      e.stopPropagation()
      const num = parseNumericValue(displayValue)
      field.onChange(num)

      if (enterAction) {
        const event = new CustomEvent("form-key-action", {
          detail: { key: "Enter", action: enterAction, field: name },
          bubbles: true,
        })
        ;(e.currentTarget as HTMLElement).dispatchEvent(event)
      } else {
        e.currentTarget.blur()
      }
    } else if (e.key === "Escape") {
      e.preventDefault()
      e.stopPropagation()

      if (escapeAction === "clear") {
        isClearingRef.current = true
        setDisplayValue("")
        field.onChange(undefined)
      }

      if (escapeAction) {
        const event = new CustomEvent("form-key-action", {
          detail: { key: "Escape", action: escapeAction, field: name },
          bubbles: true,
        })
        ;(e.currentTarget as HTMLElement).dispatchEvent(event)
      }

      if (!escapeAction || escapeAction === "clear") {
        e.currentTarget.blur()
      }
    }
  }

  return (
    <Input
      type="text"
      inputMode="decimal"
      placeholder={def.placeholder}
      value={displayValue}
      onChange={handleChange}
      onFocus={handleFocus}
      onBlur={handleBlur}
      onKeyDown={handleKeyDown}
      disabled={def.disabled}
      readOnly={def.readonly}
      tabIndex={def.readonly ? -1 : undefined}
      className={cn("text-right tabular-nums", errorClass, readonlyClass)}
    />
  )
}

// ─── DateTimeWidget ───────────────────────────────────────────────────────────

function DateTimeWidget({
  field,
  def,
  hasError = false,
}: {
  field: ControllerRenderProps<FieldValues, string>
  def: TsDateTimeField
  hasError?: boolean
}) {
  const [open, setOpen] = React.useState(false)
  const [isFocused, setIsFocused] = React.useState(false)

  const dateFormat = def.dateFormat || "d.M.yyyy HH:mm"
  const [inputValue, setInputValue] = React.useState(() => {
    const dateValue = field.value ? new Date(field.value as string | number | Date) : undefined
    const validDate = dateValue && !isNaN(dateValue.getTime()) ? dateValue : undefined
    return validDate ? format(validDate, dateFormat) : ""
  })

  const errorClass = hasError ? "border-destructive focus-visible:ring-destructive" : ""

  // Only sync input from field value when not focused
  React.useEffect(() => {
    if (isFocused) return
    const dateValue = field.value ? new Date(field.value as string | number | Date) : undefined
    const validDate = dateValue && !isNaN(dateValue.getTime()) ? dateValue : undefined
    if (validDate && !open) {
      setInputValue(format(validDate, dateFormat))
    } else if (!field.value) {
      setInputValue("")
    }
  }, [field.value, dateFormat, open, isFocused])

  const getValidDate = () => {
    const dateValue = field.value ? new Date(field.value as string | number | Date) : undefined
    return dateValue && !isNaN(dateValue.getTime()) ? dateValue : undefined
  }

  const getTimeValue = () => {
    const vd = getValidDate()
    return vd
      ? `${String(vd.getHours()).padStart(2, "0")}:${String(vd.getMinutes()).padStart(2, "0")}`
      : ""
  }

  const handleDateSelect = (date: Date | undefined) => {
    if (!date) {
      field.onChange(undefined)
      return
    }
    const newDate = new Date(date)
    const vd = getValidDate()
    if (vd) {
      newDate.setHours(vd.getHours(), vd.getMinutes(), 0, 0)
    }
    field.onChange(newDate)
  }

  const handleTimeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const parts = e.target.value.split(":")
    const hours = parseInt(parts[0] || "0")
    const minutes = parseInt(parts[1] || "0")
    const newDate = getValidDate() ? new Date(getValidDate()!) : new Date()
    newDate.setHours(hours, minutes, 0, 0)
    field.onChange(newDate)
  }

  const handleInputBlur = () => {
    setIsFocused(false)
    if (!inputValue.trim()) {
      field.onChange(undefined)
      return
    }
    const parsed = parse(inputValue, dateFormat, new Date())
    if (isValidDate(parsed)) {
      field.onChange(parsed)
    } else {
      const vd = getValidDate()
      setInputValue(vd ? format(vd, dateFormat) : "")
    }
  }

  return (
    <Popover open={open} onOpenChange={def.readonly || def.disabled ? undefined : setOpen}>
      <div className="relative">
        <Input
          value={inputValue}
          onChange={(e) => setInputValue(e.target.value)}
          onFocus={(e) => {
            if (def.readonly) {
              e.currentTarget.blur()
              return
            }
            setIsFocused(true)
            if (def.selectAllOnFocus) {
              const el = e.currentTarget
              setTimeout(() => el.select(), 0)
            }
          }}
          onClick={(e) => {
            if (def.selectAllOnFocus) e.currentTarget.select()
          }}
          onBlur={handleInputBlur}
          placeholder={def.placeholder || dateFormat.toLowerCase()}
          disabled={def.disabled}
          readOnly={def.readonly}
          tabIndex={def.readonly ? -1 : undefined}
          className={cn(
            "pr-10 text-right",
            errorClass,
            def.readonly ? "focus-visible:ring-0 focus-visible:border-input" : ""
          )}
        />
        <PopoverTrigger asChild>
          <Button
            variant="ghost"
            size="icon"
            className={cn(
              "absolute right-0 top-0 h-full w-9 rounded-l-none text-muted-foreground hover:text-foreground",
              (def.readonly || def.disabled) && "pointer-events-none"
            )}
            disabled={def.disabled}
            type="button"
          >
            <CalendarIcon className="h-4 w-4" />
          </Button>
        </PopoverTrigger>
      </div>
      <PopoverContent className="w-auto p-0" align="start">
        <Calendar
          mode="single"
          selected={getValidDate()}
          onSelect={handleDateSelect}
          initialFocus
        />
        <div className="border-t p-3">
          <div className="flex items-center gap-2">
            <span className="text-sm text-muted-foreground w-10">Time</span>
            <Input
              type="time"
              value={getTimeValue()}
              onChange={handleTimeChange}
              className="h-8 text-sm text-right"
            />
          </div>
        </div>
      </PopoverContent>
    </Popover>
  )
}

// ─── FileUploadWidget ─────────────────────────────────────────────────────────

function FileUploadWidget({
  field,
  def,
  hasError = false,
}: {
  field: ControllerRenderProps<FieldValues, string>
  def: TsFileField
  hasError?: boolean
}) {
  const [isDragOver, setIsDragOver] = React.useState(false)
  const inputRef = React.useRef<HTMLInputElement>(null)
  const accept = def.accept || (def.type === "image" ? "image/*" : undefined)
  const multiple = def.multiple

  const files: File[] = React.useMemo(() => {
    if (!field.value) return []
    if (Array.isArray(field.value)) return (field.value as File[]).filter((f) => f instanceof File)
    if (field.value instanceof File) return [field.value]
    return []
  }, [field.value])

  const handleFiles = (fileList: FileList) => {
    const newFiles = Array.from(fileList)
    if (multiple) {
      field.onChange([...files, ...newFiles])
    } else {
      field.onChange(newFiles[0])
    }
  }

  const removeFile = (index: number) => {
    if (multiple) {
      const updated = [...files]
      updated.splice(index, 1)
      field.onChange(updated.length > 0 ? updated : undefined)
    } else {
      field.onChange(undefined)
    }
  }

  const downloadFile = (file: File) => {
    const url = URL.createObjectURL(file)
    const a = document.createElement("a")
    a.href = url
    a.download = file.name
    a.click()
    setTimeout(() => URL.revokeObjectURL(url), 1000)
  }

  const formatSize = (bytes: number) => {
    if (bytes < 1024) return `${bytes} B`
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`
    return `${(bytes / 1024 / 1024).toFixed(1)} MB`
  }

  const errorBorderClass = hasError
    ? "border-destructive"
    : "border-dashed border-muted-foreground/40"
  const isInteractive = !def.disabled && !def.readonly

  return (
    <div className="flex flex-col gap-2">
      {/* Drop zone */}
      <div
        className={cn(
          "flex flex-col items-center justify-center gap-2 rounded-lg border-2 p-6 text-center transition-colors",
          errorBorderClass,
          isInteractive && "cursor-pointer hover:border-primary hover:bg-muted/30",
          isDragOver && "border-primary bg-primary/5",
          !isInteractive && "opacity-50"
        )}
        onClick={() => isInteractive && inputRef.current?.click()}
        onDragOver={(e) => {
          e.preventDefault()
          if (isInteractive) setIsDragOver(true)
        }}
        onDragLeave={() => setIsDragOver(false)}
        onDrop={(e) => {
          e.preventDefault()
          setIsDragOver(false)
          if (isInteractive && e.dataTransfer.files.length > 0) handleFiles(e.dataTransfer.files)
        }}
      >
        <CloudUpload className="h-8 w-8 text-muted-foreground" />
        <div className="text-sm text-muted-foreground">
          {def.innerLabel ||
            (multiple ? "Drop files here or click to upload" : "Drop file here or click to upload")}
        </div>
        {accept && <div className="text-xs text-muted-foreground/70">{accept}</div>}
      </div>

      {/* Hidden file input */}
      <input
        ref={inputRef}
        type="file"
        accept={accept}
        multiple={multiple}
        className="hidden"
        onChange={(e) => {
          if (e.target.files && e.target.files.length > 0) handleFiles(e.target.files)
          e.target.value = ""
        }}
      />

      {/* File list */}
      {files.length > 0 && (
        <div className="space-y-1">
          {files.map((file, index) => (
            <div
              key={`${file.name}-${index}`}
              className="flex items-center gap-2 rounded-md border bg-muted/30 px-3 py-2 text-sm"
            >
              <FileTextIcon className="h-4 w-4 text-muted-foreground shrink-0" />
              <span className="flex-1 truncate">{file.name}</span>
              <span className="text-xs text-muted-foreground shrink-0">
                {formatSize(file.size)}
              </span>
              <button
                type="button"
                className="shrink-0 text-muted-foreground hover:text-foreground"
                onClick={() => downloadFile(file)}
                title="Download"
              >
                <Download className="h-4 w-4" />
              </button>
              {isInteractive && (
                <button
                  type="button"
                  className="shrink-0 text-muted-foreground hover:text-destructive"
                  onClick={() => removeFile(index)}
                  title="Remove"
                >
                  <XIcon className="h-4 w-4" />
                </button>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

// ─── ProcessButtonGroup ───────────────────────────────────────────────────────

function ProcessButtonGroup({
  field,
  def,
}: {
  field: ControllerRenderProps<FieldValues, string>
  def: TsButtonGroupField
  hasError?: boolean
}) {
  const options = (def.options || []).map((opt: TsFieldOptions | string) => {
    if (typeof opt === "string") {
      const parts = opt.split("/")
      // Format: value/enabled/variant/label
      const value = parts[0]
      const isEnabled = parts[1] !== "false"
      const variant = parts[2] || undefined
      const label = parts[3] || parts[0]
      return { value, label, variant, disabled: !isEnabled }
    }
    return {
      value: String(opt.value),
      label: opt.label,
      variant: opt.variant,
      disabled: opt.disabled,
    }
  })

  const ARROW = 12

  const getClipPath = (): string => {
    // Arrow shape: pointed right, notched left (for all buttons)
    return `polygon(0 0, calc(100% - ${ARROW}px) 0, 100% 50%, calc(100% - ${ARROW}px) 100%, 0 100%, ${ARROW}px 50%)`
  }

  const getBgClass = (variant: string | undefined, isActive: boolean): string => {
    if (isActive) {
      switch (variant) {
        case "success":
          return "bg-green-600 text-white dark:bg-green-500 hover:bg-green-700 dark:hover:bg-green-400"
        case "destructive":
        case "danger":
          return "bg-destructive text-destructive-foreground hover:bg-destructive/90"
        case "warning":
          return "bg-amber-500 text-white hover:bg-amber-600"
        case "secondary":
          return "bg-secondary text-secondary-foreground hover:bg-secondary/80"
        default:
          return "bg-primary text-primary-foreground hover:bg-primary/90"
      }
    } else {
      // Inactive but with variant - dimmed color
      switch (variant) {
        case "success":
          return "bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400 hover:bg-green-200"
        case "destructive":
        case "danger":
          return "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400 hover:bg-red-200"
        case "warning":
          return "bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400 hover:bg-amber-200"
        case "secondary":
          return "bg-secondary/30 text-secondary-foreground hover:bg-secondary/50"
        default:
          return "bg-muted text-muted-foreground hover:bg-accent hover:text-accent-foreground"
      }
    }
  }

  return (
    <div className="flex items-stretch">
      {options.map((opt, index) => {
        const isActive = field.value === opt.value
        const clipPath = getClipPath()
        const isInteractive = !def.disabled && !def.readonly

        return (
          <div
            key={opt.value}
            className="relative h-10"
            style={{
              marginLeft: index > 0 ? `${-ARROW}px` : undefined,
              // Active button should be on top of its neighbors
              zIndex: isActive ? 10 : options.length - index,
            }}
          >
            <button
              type="button"
              disabled={def.disabled || opt.disabled}
              onClick={() => {
                if (isInteractive && !opt.disabled) field.onChange(opt.value)
              }}
              className={cn(
                "relative h-full px-10 text-sm font-medium transition-colors",
                getBgClass(opt.variant, isActive),
                (def.disabled || opt.disabled) && "opacity-50 cursor-not-allowed",
                def.readonly && "pointer-events-none"
              )}
              style={{ clipPath }}
            >
              {opt.label}
            </button>
          </div>
        )
      })}
    </div>
  )
}

// ─── DatePickerWidget ─────────────────────────────────────────────────────────

function DatePickerWidget({
  field,
  def,
  hasError = false,
}: {
  field: ControllerRenderProps<FieldValues, string>
  def: TsDateField
  hasError?: boolean
}) {
  const [open, setOpen] = React.useState(false)
  const [isFocused, setIsFocused] = React.useState(false)

  const dateFormat = def.dateFormat || "d.M.yyyy"
  const [inputValue, setInputValue] = React.useState(() => {
    const dateValue = field.value ? new Date(field.value as string | number | Date) : undefined
    const validDate = dateValue && !isNaN(dateValue.getTime()) ? dateValue : undefined
    return validDate ? format(validDate, dateFormat) : ""
  })

  // Compute calendar date from inputValue first, then field.value as fallback
  const calendarDate = React.useMemo(() => {
    if (inputValue.trim()) {
      const parsed = parse(inputValue, dateFormat, new Date())
      if (isValidDate(parsed)) return parsed
    }
    const dv = field.value ? new Date(field.value as string | number | Date) : undefined
    return dv && !isNaN(dv.getTime()) ? dv : undefined
  }, [inputValue, dateFormat, field.value])

  const errorClass = hasError ? "border-destructive focus-visible:ring-destructive" : ""

  // Only sync input from field value when not focused
  React.useEffect(() => {
    if (isFocused) return
    const dateValue = field.value ? new Date(field.value as string | number | Date) : undefined
    const validDate = dateValue && !isNaN(dateValue.getTime()) ? dateValue : undefined
    if (validDate && !open) {
      setInputValue(format(validDate, dateFormat))
    } else if (!field.value) {
      setInputValue("")
    }
  }, [field.value, dateFormat, open, isFocused])

  const handleInputBlur = () => {
    setIsFocused(false)
    if (!inputValue.trim()) {
      field.onChange(undefined)
      return
    }
    const parsed = parse(inputValue, dateFormat, new Date())
    if (isValidDate(parsed)) {
      field.onChange(parsed)
    } else {
      // Revert to valid value if parsing fails
      const dateValue = field.value ? new Date(field.value as string | number | Date) : undefined
      const validDate = dateValue && !isNaN(dateValue.getTime()) ? dateValue : undefined
      setInputValue(validDate ? format(validDate, dateFormat) : "")
    }
  }

  return (
    <Popover open={open} onOpenChange={def.readonly || def.disabled ? undefined : setOpen}>
      <div className="relative">
        <Input
          value={inputValue}
          onChange={(e) => setInputValue(e.target.value)}
          onFocus={(e) => {
            if (def.readonly) {
              e.currentTarget.blur()
              return
            }
            setIsFocused(true)
            if (def.selectAllOnFocus) {
              const el = e.currentTarget
              setTimeout(() => el.select(), 0)
            }
          }}
          onClick={(e) => {
            if (def.selectAllOnFocus) e.currentTarget.select()
          }}
          onBlur={handleInputBlur}
          placeholder={def.placeholder || dateFormat.toLowerCase()}
          disabled={def.disabled}
          readOnly={def.readonly}
          tabIndex={def.readonly ? -1 : undefined}
          className={cn(
            "pr-10 text-right",
            errorClass,
            def.readonly ? "focus-visible:ring-0 focus-visible:border-input" : ""
          )}
        />
        <PopoverTrigger asChild>
          <Button
            variant="ghost"
            size="icon"
            className={cn(
              "absolute right-0 top-0 h-full w-9 rounded-l-none text-muted-foreground hover:text-foreground",
              (def.readonly || def.disabled) && "pointer-events-none"
            )}
            disabled={def.disabled}
            type="button"
          >
            <CalendarIcon className="h-4 w-4" />
          </Button>
        </PopoverTrigger>
      </div>
      <PopoverContent className="w-auto p-0" align="start">
        <Calendar
          mode="single"
          selected={calendarDate}
          defaultMonth={calendarDate}
          onSelect={(date) => {
            if (date) field.onChange(date)
            setOpen(false)
          }}
          initialFocus
        />
      </PopoverContent>
    </Popover>
  )
}

// ─── SliderWithTooltip ────────────────────────────────────────────────────────

function SliderWithTooltip({
  field,
  def,
  hasError = false,
}: {
  field: ControllerRenderProps<FieldValues, string>
  def: TsSliderField
  hasError?: boolean
}) {
  const [showTooltip, setShowTooltip] = React.useState(false)
  const [localValue, setLocalValue] = React.useState<number>(field.value ?? def.min ?? 0)
  const readonlyPointerClass = def.readonly ? "pointer-events-none" : ""

  React.useEffect(() => {
    setLocalValue(field.value ?? def.min ?? 0)
  }, [field.value, def.min])

  const min = def.min ?? 0
  const max = def.max ?? 100
  const percent =
    max !== min ? Math.min(100, Math.max(0, ((localValue - min) / (max - min)) * 100)) : 0

  return (
    <div className={cn("relative py-2", readonlyPointerClass)}>
      {showTooltip && (
        <div
          className="absolute -top-7 -translate-x-1/2 pointer-events-none whitespace-nowrap rounded-md border bg-popover text-popover-foreground px-2 py-0.5 text-xs shadow-md z-50"
          style={{ left: `${percent}%` }}
        >
          {localValue}
        </div>
      )}
      <Slider
        value={[localValue]}
        max={max}
        min={min}
        step={def.step || 1}
        onValueChange={(vals: number[]) => {
          setLocalValue(vals[0])
          setShowTooltip(true)
        }}
        onValueCommit={(vals: number[]) => {
          field.onChange(vals[0])
          setTimeout(() => setShowTooltip(false), 300)
        }}
        onPointerDown={() => setShowTooltip(true)}
        onPointerEnter={() => setShowTooltip(true)}
        onPointerLeave={() => setShowTooltip(false)}
        disabled={def.disabled}
        className={cn(
          hasError && "**:[[role=slider]]:border-destructive **:[[role=slider]]:bg-destructive"
        )}
      />
    </div>
  )
}

function MarkdownCopyButton({ text }: { text: string }) {
  const [copied, setCopied] = React.useState(false)

  const copy = () => {
    navigator.clipboard.writeText(text)
    setCopied(true)
    setTimeout(() => setCopied(false), 2000)
  }

  return (
    <Button
      variant="ghost"
      size="icon-xs"
      className="absolute right-2 top-2 opacity-0 group-hover:opacity-100 transition-opacity"
      onClick={copy}
    >
      {copied ? <Check className="h-3 w-3" /> : <Copy className="h-3 w-3" />}
    </Button>
  )
}

"use client"

import * as React from "react"

import { Separator } from "@/components/ui/separator"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"

import { TsFormField } from "./ts-form-field"
import { TsFormLayout as LayoutType, TsFieldDef, TsFormRow } from "./types"

interface TsFormLayoutProps {
  layout: LayoutType
  fields: Record<string, TsFieldDef>
}

export function TsFormLayout({ layout, fields }: TsFormLayoutProps) {
  if (layout.tabs) {
    return (
      <Tabs defaultValue={layout.tabs[0].label} className="w-full">
        <TabsList className="w-full justify-start">
          {layout.tabs.map((tab, index) => (
            <TabsTrigger key={index} value={tab.label}>
              {tab.label}
            </TabsTrigger>
          ))}
        </TabsList>
        {layout.tabs.map((tab, index) => (
          <TabsContent key={index} value={tab.label} className="space-y-4 pt-4">
            {renderRows(tab.rows, fields)}
          </TabsContent>
        ))}
      </Tabs>
    )
  }

  if (layout.rows) {
    return <div className="space-y-4">{renderRows(layout.rows, fields)}</div>
  }

  return null
}

function renderRows(rows: TsFormRow[], fields: Record<string, TsFieldDef>) {
  return rows.map((row, rowIndex) => {
    // Calculate grid template columns based on widths
    // Default width is 1fr if not specified
    const gridTemplateColumns = row.map((item) => item.width || "1fr").join(" ")

    return (
      <div key={rowIndex} className="grid gap-4 items-start" style={{ gridTemplateColumns }}>
        {row.map((item, colIndex) => {
          if (item.type === "empty") {
            return <div key={colIndex} />
          }

          if (item.type === "separator") {
            return (
              <div key={colIndex} className="col-span-full py-2">
                {item.label && (
                  <h4 className="text-sm font-medium text-muted-foreground mb-2">{item.label}</h4>
                )}
                <Separator />
              </div>
            )
          }

          const fieldDef = fields[item.field]
          if (!fieldDef) {
            return (
              <div key={colIndex} className="text-destructive text-sm">
                Field &apos;{item.field}&apos; not found
              </div>
            )
          }

          return <TsFormField key={colIndex} name={item.field} fieldDef={fieldDef} />
        })}
      </div>
    )
  })
}

import { z } from "zod"

import { TsFieldDef } from "./types"

export function generateZodSchema(fields: Record<string, TsFieldDef>) {
  const shape: Record<string, z.ZodTypeAny> = {}

  Object.entries(fields).forEach(([key, def]) => {
    if (def.type === "separator" || def.type === "empty" || def.type === "button") {
      return
    }

    let schema: z.ZodTypeAny

    switch (def.type) {
      case "number":
      case "slider":
        schema = z.number()
        if (def.min !== undefined) schema = (schema as z.ZodNumber).min(def.min)
        if (def.max !== undefined) schema = (schema as z.ZodNumber).max(def.max)

        // If not required, allow null/undefined
        if (!def.required) {
          schema = schema.nullish()
        }
        break

      case "checkbox":
      case "switch":
        schema = z.boolean().default(false)
        break

      case "date":
      case "datetime":
        schema = z.date()
        if (!def.required) schema = schema.nullish()
        break

      default: // text, select, etc. (mostly strings)
        if (def.required) {
          schema = z.string().min(1, { message: "This field is required" })
        } else {
          schema = z.string().optional().or(z.literal(""))
        }
        break
    }

    shape[key] = schema
  })

  return z.object(shape)
}

import type { ReactNode } from "react"

import { TsTableColumnDef } from "@/components/ts-web-ui/ts-table/columns"

export type FieldType =
  | "text"
  | "textarea"
  | "password"
  | "number"
  | "slider"
  | "select"
  | "multiselect"
  | "combobox"
  | "radio"
  | "checkbox"
  | "switch"
  | "date"
  | "datetime"
  | "file"
  | "image"
  | "button"
  | "separator"
  | "empty"
  | "table" // nested
  | "relationship"
  | "infobox"
  | "markdown"
  | "button-group"

// ─── Variant unions ────────────────────────────────────────────────────────────

export type TsButtonVariant =
  | "default"
  | "primary"
  | "secondary"
  | "destructive"
  | "outline"
  | "ghost"
  | "link"
  | "danger"
  | "success"
  | "warning"

export type TsInfoboxVariant = "default" | "information" | "warning" | "success" | "destructive"

// ─── Options ──────────────────────────────────────────────────────────────────

export interface TsFieldOptions {
  label: string
  value: string | number | boolean
  /** Button variant used when this option is the active selection (button-group) */
  variant?: TsButtonVariant
  disabled?: boolean
}

// ─── Shared base properties (present on every field type) ─────────────────────

interface TsFieldBase {
  label?: string
  required?: boolean
  hidden?: boolean
  disabled?: boolean
  readonly?: boolean
  hint?: string
  /** Error message – when set, the widget renders in error/danger state */
  error?: string
}

// ─── Shared behaviour mixins ───────────────────────────────────────────────────

interface TsFieldInputBehavior {
  placeholder?: string
  /** Select all text when the field is focused or clicked */
  selectAllOnFocus?: boolean
  /** Action emitted when Enter is pressed (e.g. 'focus:next', 'submit', 'click:save') */
  enterAction?: string
  /** Action on Escape: 'clear' clears the value, any other string emits form-key-action */
  escapeAction?: string
}

interface TsFieldNumericRange {
  min?: number
  max?: number
  step?: number
}

interface TsFieldWithOptions {
  placeholder?: string
  options?: TsFieldOptions[] | string[]
  /** Message shown when no option matches the search (default: "Not found.") */
  notFoundMessage?: string
}

// ─── Per-type field interfaces ─────────────────────────────────────────────────

export interface TsTextField extends TsFieldBase, TsFieldInputBehavior {
  type: "text" | "password"
}

export interface TsTextareaField extends TsFieldBase, TsFieldInputBehavior {
  type: "textarea"
  rows?: number
}

export interface TsNumberField extends TsFieldBase, TsFieldInputBehavior, TsFieldNumericRange {
  type: "number"
  /** Number of decimal places for rounding and display */
  roundTo?: number
}

export interface TsSliderField extends TsFieldBase, TsFieldNumericRange {
  type: "slider"
}

export interface TsSelectField extends TsFieldBase {
  type: "select"
  placeholder?: string
  options?: TsFieldOptions[] | string[]
}

export interface TsMultiselectField extends TsFieldBase, TsFieldWithOptions {
  type: "multiselect"
}

export interface TsComboboxField extends TsFieldBase, TsFieldWithOptions {
  type: "combobox"
  /** Allow the user to enter a custom value not present in the options list */
  allowCustom?: boolean
  selectAllOnFocus?: boolean
}

export interface TsRadioField extends TsFieldBase {
  type: "radio"
  options?: TsFieldOptions[] | string[]
}

export interface TsCheckboxField extends TsFieldBase {
  type: "checkbox"
}

export interface TsSwitchField extends TsFieldBase {
  type: "switch"
}

export interface TsButtonGroupField extends TsFieldBase {
  type: "button-group"
  options?: TsFieldOptions[] | string[]
  /** "process" renders a chevron-style process stepper; omit for a standard button group */
  variant?: "process"
}

export interface TsDateField extends TsFieldBase {
  type: "date"
  placeholder?: string
  /** Date format string using date-fns tokens (default: "d.M.yyyy") */
  dateFormat?: string
  selectAllOnFocus?: boolean
}

export interface TsDateTimeField extends TsFieldBase {
  type: "datetime"
  placeholder?: string
  /** Date format string using date-fns tokens (default: "d.M.yyyy HH:mm") */
  dateFormat?: string
  selectAllOnFocus?: boolean
}

export interface TsFileField extends TsFieldBase {
  type: "file" | "image"
  /** Accepted file types (e.g. ".pdf,.doc" or "image/*") */
  accept?: string
  /** Allow multiple file selection */
  multiple?: boolean
  /** Label shown inside the drop zone */
  innerLabel?: string
}

export interface TsButtonField extends TsFieldBase {
  type: "button"
  /** Action name emitted when the button is clicked */
  action?: string
  variant?: TsButtonVariant
}

export interface TsSeparatorField extends TsFieldBase {
  type: "separator"
}

export interface TsEmptyField extends TsFieldBase {
  type: "empty"
}

export interface TsTableField extends TsFieldBase {
  type: "table"
  columns?: TsTableColumnDef[]
  showCreateButton?: boolean
}

export interface TsRelationshipField extends TsFieldBase {
  type: "relationship"
  placeholder?: string
  /** Entity name used for placeholder text and search label */
  targetEntity?: string
  /** Single or multiple selection */
  mode?: "single" | "multiple"
  /** Field names to display in search results */
  displayFields?: string[]
  /** Field names to display inside the selected chip */
  chipDisplayFields?: string[]
  /** Field used as the stored value / primary key */
  valueField?: string
  /** Available records to select from */
  options?: Record<string, unknown>[]
}

export interface TsInfoboxField extends TsFieldBase {
  type: "infobox"
  content?: string
  value?: ReactNode
  variant?: TsInfoboxVariant
}

export interface TsMarkdownField extends TsFieldBase {
  type: "markdown"
  content?: string
  value?: string
}

// ─── Main discriminated union ──────────────────────────────────────────────────
/**
 * Field definition for a single form widget.
 *
 * The `type` discriminant narrows all other properties so IDE autocomplete only
 * shows properties that are valid for the chosen widget type.
 *
 * @example
 * ```ts
 * const fields: Record<string, TsFieldDef> = {
 *   name:   { type: "text",   label: "Name", required: true },
 *   age:    { type: "number", min: 0, max: 150, roundTo: 0 },
 *   status: { type: "infobox", variant: "warning", content: "..." },
 * }
 * ```
 */
export type TsFieldDef =
  | TsTextField
  | TsTextareaField
  | TsNumberField
  | TsSliderField
  | TsSelectField
  | TsMultiselectField
  | TsComboboxField
  | TsRadioField
  | TsCheckboxField
  | TsSwitchField
  | TsButtonGroupField
  | TsDateField
  | TsDateTimeField
  | TsFileField
  | TsButtonField
  | TsSeparatorField
  | TsEmptyField
  | TsTableField
  | TsRelationshipField
  | TsInfoboxField
  | TsMarkdownField

// ─── Utility type for partial updates (used internally by the form editor) ────
/**
 * All possible field properties combined as optional.
 * Use this for partial config updates in the form editor instead of `Partial<TsFieldDef>`.
 */
export interface TsFieldUpdate {
  type?: FieldType
  label?: string
  required?: boolean
  hidden?: boolean
  disabled?: boolean
  readonly?: boolean
  placeholder?: string
  hint?: string
  error?: string
  // Number / slider
  min?: number
  max?: number
  step?: number
  roundTo?: number
  // Options-bearing fields
  options?: TsFieldOptions[] | string[] | Record<string, unknown>[]
  notFoundMessage?: string
  // Textarea
  rows?: number
  // File
  accept?: string
  multiple?: boolean
  innerLabel?: string
  // Relationship
  targetEntity?: string
  mode?: "single" | "multiple"
  displayFields?: string[]
  chipDisplayFields?: string[]
  valueField?: string
  // Table
  columns?: TsTableColumnDef[]
  showCreateButton?: boolean
  // Button
  action?: string
  // Combobox
  allowCustom?: boolean
  // Text / number / date inputs
  selectAllOnFocus?: boolean
  enterAction?: string
  escapeAction?: string
  // Date / datetime
  dateFormat?: string
  // Infobox / markdown
  content?: string
  value?: unknown
  // Variant (infobox, button, button-group)
  variant?: TsButtonVariant | TsInfoboxVariant | "process"
}

// ─── Form layout ──────────────────────────────────────────────────────────────

export interface TsFormRowItem {
  field: string // Key referencing fields object, or special type like 'empty'
  width?: string // CSS grid width (e.g. '1fr', '200px')
  type?: "empty" | "separator"
  label?: string // For separator
  align?: "left" | "center" | "right"
}

export type TsFormRow = TsFormRowItem[]

export interface TsFormTab {
  label: string
  rows: TsFormRow[]
}

export interface TsFormLayout {
  tabs?: TsFormTab[]
  rows?: TsFormRow[]
}

// ─── Form buttons ─────────────────────────────────────────────────────────────

export interface TsFormConfirmation {
  title: string
  text: string
  buttons: {
    action: string
    label: string
    variant?: TsButtonVariant
    confirm?: boolean
    position?: "left" | "center" | "right"
  }[]
}

export interface TsFormButton {
  action: string
  label: string
  variant?: TsButtonVariant
  type?: "submit" | "button" | "reset"
  icon?: string
  position?: "left" | "center" | "right"
  confirmation?: TsFormConfirmation
}
